import * as THREE from "three";
import * as CANNON from "cannon-es";
import { TASK, SMOKE, trial } from "./task.mjs";
import { describeScene, validateDesc } from "./world.mjs";
import { runTrial } from "./trialrun.mjs";

function makeBuild(params) {
  return function build({ THREE, add, task }) {
    const t = 0.012;
    const {
      ax = -0.96, ay = 0.70, az = -0.35,
      cx = 0.0, cy = 0.36, cz = 0.0,
      bx = 0.73, by = 0.06, bz = 0.273,
      w1 = 0.075, h1 = 0.065,
      w2 = 0.08, h2 = 0.065,
      fLen = 0.22, fH = 0.11, fAngle = 0.65,
      fApexX = 0.875, fApexZ = 0.328, fY = 0.08
    } = params;

    function addChannel(p0, p1, width, wallH, floorExtend0 = 0, floorExtend1 = 0, wallExtend0 = 0, wallExtend1 = 0) {
      const A = new THREE.Vector3(...p0);
      const B = new THREE.Vector3(...p1);
      const d = new THREE.Vector3().subVectors(B, A);
      const L = d.length();
      const u = d.clone().normalize();
      const up = new THREE.Vector3(0, 1, 0);
      const w = new THREE.Vector3().crossVectors(u, up).normalize();
      const v = new THREE.Vector3().crossVectors(w, u).normalize();
      const mat = new THREE.Matrix4().makeBasis(u, v, w);
      const e = new THREE.Euler().setFromRotationMatrix(mat, "XYZ");
      const rot = [e.x, e.y, e.z];

      const fL = L + floorExtend0 + floorExtend1;
      const fMid = A.clone().addScaledVector(u, (L + floorExtend1 - floorExtend0) / 2).addScaledVector(v, -t / 2);
      add.box({
        size: [fL, t, width],
        position: [fMid.x, fMid.y, fMid.z],
        rotation: rot,
      });

      const wL = L + wallExtend0 + wallExtend1;
      const wMidBase = A.clone().addScaledVector(u, (L + wallExtend1 - wallExtend0) / 2).addScaledVector(v, wallH / 2 - t);
      for (const s of [-1, 1]) {
        const wPos = wMidBase.clone().addScaledVector(w, s * (width / 2 + t / 2));
        add.box({
          size: [wL, wallH, t],
          position: [wPos.x, wPos.y, wPos.z],
          rotation: rot,
        });
      }
    }

