    const baseYaw = Math.atan2(-(bz - cz), bx - cx);
    const dirX = (bx - cx) / Math.hypot(bx - cx, bz - cz);
    const dirZ = (bz - cz) / Math.hypot(bx - cx, bz - cz);
    const sideX = -dirZ, sideZ = dirX;

